import spidev
import time
import os
import signal
from threading import Thread

class LoadCellReader:
    def __init__(self):
        self.spi = spidev.SpiDev()
        self.spi.open(0, 0)
        self.spi.max_speed_hz = 50000
        self.spi.mode = 0b00
        self.spi.bits_per_word = 8

    def send_spi_command(self, data):
        try:
            return self.spi.xfer2([0x01, 0x80, 0x00])
        except (OSError, IOError) as e:
            print(f"Error during SPI transfer: {e}")
            self.close()
            os.kill(os.getpid(), signal.SIGTERM)

    def extract_10bit(self, response):
        return ((response[1] & 0x03) << 8) | response[2]

    def read_raw_data(self):
        response = self.send_spi_command([0x01, 0x80, 0x00])
        raw_data = self.extract_10bit(response)
        return raw_data

    def convert_to_weight(self, raw_data):
        weight = float(raw_data) * (5.0 / 1023.0)
        return weight

    def close(self):
        self.spi.close()

def main():
    reader = LoadCellReader()
    try:
        while True:
            raw_data = reader.read_raw_data()
            weight = reader.convert_to_weight(raw_data)
            print(f"Weight: {weight:.2f} kg")
            time.sleep(0.5)
    except (KeyboardInterrupt, SystemExit):
        print("Shutting down...")
    finally:
        reader.close()

if __name__ == "__main__":
    main()

