import spidev
import RPi.GPIO as GPIO
import time

class SmartGardenController:
    def __init__(self):
        self.spi = spidev.SpiDev()
        self.spi.open(0, 0)
        self.spi.max_speed_hz = 1350000
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(18, GPIO.OUT)

    def read_moisture(self):
        adc = self.spi.xfer2([1, (8 + 0) << 4, 0])
        data = ((adc[1] & 3) << 8) + adc[2]
        return data

    def run_pump(self, seconds):
        GPIO.output(18, GPIO.HIGH)
        time.sleep(seconds)
        GPIO.output(18, GPIO.LOW)

    def irrigation_cycle(self):
        moisture_level = self.read_moisture()
        print(f"Moisture level: {moisture_level}")
        if moisture_level < 450:
            self.run_pump(2)
            return True
        return False

    def close(self):
        self.spi.close()
        GPIO.cleanup()

def schedule_cycles(controller, cycle_count, interval_seconds):
    try:
        for _ in range(cycle_count):
            watered = controller.irrigation_cycle()
            if watered:
                print("Soil watered.")
            else:
                print("Soil not watered.")
            time.sleep(interval_seconds)
    except KeyboardInterrupt:
        print("Interrupted by user.")
    finally:
        controller.close()

if __name__ == "__main__":
    controller = SmartGardenController()
    try:
        schedule_cycles(controller, 10, 3)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        controller.close()

import RPi.GPIO as GPIO
import spidev
import time
import queue
import logging

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins=None, channels=None, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.stop_event = threading.Event()

        if sensor_type == 'digital':
            GPIO.setmode(GPIO.BCM)
            for pin in gpio_pins:
                GPIO.setup(pin, GPIO.IN)
        elif sensor_type == 'analog':
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = spi_speed
        else:
            raise ValueError('Invalid sensor type')

    def read(self):
        if self.sensor_type == 'digital':
            for pin in self.gpio_pins:
                if GPIO.input(pin) == 1:
                    return True
            return False
        elif self.sensor_type == 'analog':
            for channel in self.channels:
                adc = self.spi.xfer2([1, (8 + channel) << 4, 0])
                data = ((adc[1] & 3) << 8) + adc[2]
                if data >= self.threshold:
                    return True
            return False
        else:
            raise ValueError('Invalid sensor type')

    def run(self):
        while not self.stop_event.is_set():
            if self.read():
                self.log_queue.put(f'Sound event detected by sensor {self.sensor_id}')
                time.sleep(0.1)
            time.sleep(1/self.sample_rate)

    def stop(self):
        self.stop_event.set()
        if self.sensor_type == 'digital':
            GPIO.cleanup()

def main():
    import argparse
    import threading

    parser = argparse.ArgumentParser()
    parser.add_argument('--sensor_type', choices=['digital', 'analog'])
    parser.add_argument('--threshold', type=int)
    parser.add_argument('--sample_rate', type=int)
    parser.add_argument('--log_file')
    parser.add_argument('--gpio_pins', nargs='+', type=int)
    parser.add_argument('--channels', nargs='+', type=int)
    parser.add_argument('--spi_speed', type=int, default=1000000)
    parser.add_argument('--sensor_ids', nargs='+', type=int)
    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.INFO)

    log_queue = queue.Queue()
    sensors = []
    threads = []

    for sensor_id in args.sensor_ids:
        sensor = SoundSensor(sensor_id, args.sensor_type, args.threshold, args.sample_rate, args.gpio_pins, args.channels, args.spi_speed, log_queue)
        sensors.append(sensor)
        thread = threading.Thread(target=sensor.run)
        threads.append(thread)
        thread.start()

    try:
        while threads:
            message = log_queue.get()
            logging.info(message)
    except KeyboardInterrupt:
        for sensor in sensors:
            sensor.stop()
        for thread in threads:
            thread.join()

if __name__ == '__main__':
    main()

