import smbus2
import time

class ADS1x15:
    def __init__(self, address=0x48, bus=1):
        self.address = address
        self.bus = smbus2.SMBus(bus)
        self.conversion_delay = 0.010  # 10ms
        self.config_reg_address = 1
        self.conversion_reg_address = 0

    def _write_config(self, channel, pga):
        config = (channel << 12) | (pga << 9) | 0x8000
        self.bus.write_word_data(self.address, self.config_reg_address, config)

    def read(self, channel, pga):
        if channel < 0 or channel > 3:
            raise ValueError("Channel must be between 0 and 3")
        if pga not in [6144, 4096, 2048, 1024, 512, 256]:
            raise ValueError("PGA must be one of 6144, 4096, 2048, 1024, 512, 256")

        try:
            self._write_config(channel, pga)
            time.sleep(self.conversion_delay)
            raw_reading = self.bus.read_word_data(self.address, self.conversion_reg_address)
            scaled_reading = (raw_reading * pga) / 32768.0
            return scaled_reading
        except (OSError, smbus2.SMBusException) as e:
            raise IOError("Failed to communicate with ADS1x15: {}".format(e))

    def __del__(self):
        try:
            self.bus.close()
        except AttributeError:
            pass  # Already cleaned up

