import time
import json
import random
import logging
import RPi.GPIO as GPIO
from gpiozero import MCP3008
from signal import signal, SIGINT, SIGTERM

# Set up logging
logging.basicConfig(filename='greenhouse_monitor.log', level=logging.INFO)

# Set up GPIO
GPIO.setmode(GPIO.BCM)
GPIO.setup(17, GPIO.OUT)

# Set up MCP3008
adc = MCP3008(channel=0)

def read_soil_moisture():
    # Simulate sensor if no physical sensor is detected
    if adc.value < 0.01 or adc.value > 1.0:
        return random.randint(0, 100)
    else:
        return adc.value * 100

def read_weather_forecast():
    try:
        with open('weather_forecast.json', 'r') as file:
            data = json.load(file)
            return data.get('rain_probability', None)
    except FileNotFoundError:
        logging.warning('Weather forecast file not found.')
        return None
    except json.JSONDecodeError:
        logging.error('Invalid JSON in weather forecast file.')
        return None

def control_watering(soil_moisture, rain_probability):
    if soil_moisture < 30 and rain_probability < 0.2:
        GPIO.output(17, GPIO.HIGH)
        logging.info(f'Activating watering. Soil moisture: {soil_moisture}%, Rain probability: {rain_probability}')
    elif soil_moisture > 70:
        GPIO.output(17, GPIO.LOW)
        logging.info(f'Deactivating watering. Soil moisture: {soil_moisture}%, Rain probability: {rain_probability}')
    else:
        logging.info(f'No action needed. Soil moisture: {soil_moisture}%, Rain probability: {rain_probability}')

def signal_handler(signal, frame):
    GPIO.cleanup()
    logging.info('Exiting program.')
    exit(0)

if __name__ == '__main__':
    # Handle SIGINT and SIGTERM
    signal(SIGINT, signal_handler)
    signal(SIGTERM, signal_handler)

    while True:
        soil_moisture = read_soil_moisture()
        rain_probability = read_weather_forecast()
        control_watering(soil_moisture, rain_probability)
        time.sleep(60)

