import time
import struct
from smbus2 import i2c

# BME280 constants
BME280_ADDR = 0x76
BME280_CHIPID = 0x60
BME280_CALIB_START = 0x88
BME280_CALIB_LEN = 0x60
BME280_CTRL_HUM = 0xF2
BME280_CTRL_MEAS = 0xF4
BME280_CONFIG = 0xF5
BME280_PRESS_OSR = 0xF4
BME280_TEMP_OSR = 0xF4
BME280_HUM_OSR = 0xF2
BME280_TEMP_DIG_START = 0x88
BME280_PRESS_DIG_START = 0x8E
BME280_HUM_DIG_START = 0xA1
BME280_TEMP_DIG_LEN = 6
BME280_PRESS_DIG_LEN = 18
BME280_HUM_DIG_LEN = 7
BME280_TEMP_OSR_1X = 0x27
BME280_PRESS_OSR_1X = 0x27
BME280_HUM_OSR_1X = 0x27

# Initialize I2C bus
bus = smbus2.SMBus(1)

def read_byte(reg):
    try:
        return bus.read_byte_data(BME280_ADDR, reg)
    except i2c.I2CException as e:
        print(f"I2C error: {e}")
        return None

def read_word(reg):
    try:
        return bus.read_word_data(BME280_ADDR, reg)
    except i2c.I2CException as e:
        print(f"I2C error: {e}")
        return None

def read_word_2c(reg):
    val = read_word(reg)
    if val is not None:
        return val if val < 0x8000 else -((65535 - val) + 1)

def read_unsigned_short(reg):
    try:
        return bus.read_i2c_block_data(BME280_ADDR, reg, 2)
    except i2c.I2CException as e:
        print(f"I2C error: {e}")
        return None

def read_unsigned_short_swapped(reg):
    val = read_unsigned_short(reg)
    if val is not None:
        return struct.unpack('<H', bytes(val))[0]

def read_signed_short(reg):
    try:
        return bus.read_i2c_block_data(BME280_ADDR, reg, 2)
    except i2c.I2CException as e:
        print(f"I2C error: {e}")
        return None

def read_signed_short_swapped(reg):
    val = read_signed_short(reg)
    if val is not None:
        return struct.unpack('<h', bytes(val))[0]

def read_calibration_data():
    calibration_data = {}
    for reg in range(BME280_CALIB_START, BME280_CALIB_START + BME280_CALIB_LEN, 2):
        val = read_word_swapped(reg)
        if val is not None:
            calibration_data[reg] = val
    return calibration_data

def read_chip_id():
    return read_byte(0xD0)

def init_bme280():
    chip_id = read_chip_id()
    if chip_id != BME280_CHIPID:
        print(f"Chip ID mismatch, expected {BME280_CHIPID}, got {chip_id}")
        return False
    calibration_data = read_calibration_data()
    if not calibration_data:
        print("Failed to read calibration data")
        return False
    return calibration_data

def compensate_temp(adc_T, calibration_data):
    var1 = (((adc_T >> 3) - ((calibration_data[BME280_TEMP_DIG_START] << 1) + calibration_data[BME280_TEMP_DIG_START + 1] * 2)) * calibration_data[BME280_TEMP_DIG_START + 2]) >> 11
    var2 = (((((adc_T >> 4) - calibration_data[BME280_TEMP_DIG_START]) * ((adc_T >> 4) - calibration_data[BME280_TEMP_DIG_START + 2])) >> 12) * calibration_data[BME280_TEMP_DIG_START + 3]) >> 14
    t_fine = var1 + var2
    temp = (t_fine * 5 + 128) >> 8
    return temp / 100

def compensate_pressure(adc_P, calibration_data, t_fine):
    var1 = (t_fine >> 1) - 64000
    var2 = (((32768 + var1) * var1) >> 1) / 2
    p = (((((adc_P * 2467) / 1024) - var2) * 3125) / 256) / 128
    return p / 100

def compensate_humidity(adc_H, calibration_data, t_fine):
    var1 = t_fine - 76800
    var2 = adc_H * calibration_data[BME280_HUM_DIG_START + 1] / 65536
    var3 = (((adc_H * calibration_data[BME280_HUM_DIG_START + 3] / 65536) - (var1 * (adc_H * calibration_data[BME280_HUM_DIG_START + 2] / 65536)) / 128) + 8192) * var1 / 1024
    var4 = ((var3 * var3) / 32768) * calibration_data[BME280_HUM_DIG_START + 4] / 65536
    var5 = (var3 * (adc_H * calibration_data[BME280_HUM_DIG_START] / 65536)) / 128
    var6 = ((var5 + var4 + 32768) / 1024) * calibration_data[BME280_HUM_DIG_START + 5] / 32
    h = var6 / 1024
    return h / 1024

def measure_bme280(calibration_data):
    bus.write_byte_data(BME280_ADDR, BME280_CTRL_MEAS, BME280_TEMP_OSR_1X | BME280_PRESS_OSR_1X | BME280_HUM_OSR_1X)
    time.sleep(0.005)
    adc_P = read_unsigned_short_swapped(0xF7)
    adc_T = read_unsigned_short_swapped(0xFA)
    adc_H = read_byte(0xFD)
    t_fine = read_word_swapped(0xF6)
    temp = compensate_temp(adc_T, calibration_data)
    press = compensate_pressure(adc_P, calibration_data, t_fine)
    hum = compensate_humidity(adc_H, calibration_data, t_fine)
    return temp, press, hum

def main():
    calibration_data = init_bme280()
    if not calibration_data:
        return
    while True:
        temp, press, hum = measure_bme280(calibration_data)
        print(f"Temperature: {temp} C, Pressure: {press} hPa, Humidity: {hum} %")
        time.sleep(1)

if __name__ == "__main__":
    main()

