from typing import Tuple, Union
import math

def degrees_decimal_to_dms(degrees_decimal: float) -> Tuple[int, int, float]:
    if not isinstance(degrees_decimal, (int, float)):
        raise ValueError("Input must be a real number")

    degrees = int(degrees_decimal)
    minutes_decimal = (degrees_decimal - degrees) * 60
    minutes = int(minutes_decimal)
    seconds = (minutes_decimal - minutes) * 60

    return (degrees, minutes, seconds)

def number_to_exif_rational(number: Union[int, float]) -> Tuple[int, int]:
    if not isinstance(number, (int, float)):
        raise ValueError("Input must be a real number")

    if math.isinf(number) or math.isnan(number):
        raise ValueError("Input must be a real number")

    if number == 0:
        return (0, 1)

    if isinstance(number, int):
        return (number, 1)

    # Convert to a fraction
    denominator = 1000
    numerator = int(round(number * denominator))

    # Reduce the fraction
    gcd = math.gcd(numerator, denominator)
    numerator //= gcd
    denominator //= gcd

    if not isinstance(numerator, int) or not isinstance(denominator, int):
        raise TypeError("Numerator and denominator must be integers")

    return (numerator, denominator)

