import RPi.GPIO as GPIO
import time
import datetime
from picamera2 import Picamera2
from adafruit_dht import DHT11
import speech_recognition as sr
import paho.mqtt.client as mqtt

GPIO.setmode(GPIO.BCM)
GPIO.setup(17, GPIO.OUT)

dht11 = DHT11(4)
picam = Picamera2()
r = sr.Recognizer()

def turn_lights_on():
    try:
        GPIO.output(17, GPIO.HIGH)
    except Exception:
        print("Failed to turn lights on. Simulating GPIO mode.")

def turn_lights_off():
    try:
        GPIO.output(17, GPIO.LOW)
    except Exception:
        print("Failed to turn lights off. Simulating GPIO mode.")

def read_temperature():
    try:
        temperature = dht11.temperature
        if temperature is not None:
            return temperature
    except Exception:
        print("Failed to read temperature. Simulating temperature between 15 and 35°C.")
        return 25

def capture_image():
    try:
        picam.start_preview()
        time.sleep(2)
        picam.capture_file(f"greenhouse_{datetime.datetime.now().isoformat()}.jpg")
        picam.stop_preview()
    except Exception:
        print("Failed to capture image. Simulating camera mode.")

def on_connect(client, userdata, flags, rc):
    print(f"Connected with result code {str(rc)}")

def on_message(client, userdata, msg):
    print(msg.topic+" "+str(msg.payload))
    if "turn on the lights" in str(msg.payload):
        turn_lights_on()
    elif "turn off the lights" in str(msg.payload):
        turn_lights_off()
    elif "what is the temperature" in str(msg.payload):
        print(f"Temperature: {read_temperature()}°C")
    elif "take a picture" in str(msg.payload):
        capture_image()

def listen_for_voice_commands():
    with sr.Microphone() as source:
        print("Listening for voice commands...")
        audio = r.listen(source, timeout=5)
    try:
        print("Recognizing...")
        command = r.recognize_google(audio)
        print(f"Command: {command}")
        if "Greenhouse" in command:
            client.publish("greenhouse/command", command)
    except sr.UnknownValueError:
        print("Could not understand audio")
    except sr.RequestError as e:
        print(f"Could not request results; {e}")

def cleanup():
    GPIO.cleanup()
    picam.close()

client = mqtt.Client()
client.on_connect = on_connect
client.on_message = on_message

client.connect("mqtt.broker.url", 1883, 60)
client.loop_start()

try:
    while True:
        listen_for_voice_commands()
except KeyboardInterrupt:
    client.loop_stop()
    cleanup()

