        self.camera.configure(self.camera.preview_configuration(main={"size": (640, 480), "format": 'XRGB8888'}))
        self.camera.start()
        self.box = Box()

    def run(self):
        signal.signal(signal.SIGINT, self.exit_gracefully)
        while True:
            if self.box.is_button_up():
                frame = self.camera.capture_array()
                gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY)
                faces = self.face_cascade.detectMultiScale(gray, scaleFactor=1.1, minNeighbors=5, minSize=(30, 30))
                if len(faces) > 0:
                    (x, y, w, h) = faces[0]
                    face = gray[y:y+h, x:x+w]
                    face = cv2.resize(face, (100, 100))
                    label, conf = self.recognizer.predict(face)
                    if label == config.POSITIVE_LABEL and conf > config.POSITIVE_THRESHOLD:
                        if self.box.is_locked:
                            self.box.unlock()
                    else:
                        if not self.box.is_locked:
                            self.box.lock()
            time.sleep(0.1)

    def exit_gracefully(self, signum, frame):
        self.camera.stop()
        if not self.box.is_locked:
            self.box.lock()
        exit(0)

if __name__ == "__main__":
