        signal.signal(signal.SIGTERM, self.stop)

    def load_files(self, folder=None):
        if folder:
            self.folder = folder

        files = os.listdir(self.folder)
        if not files:
            raise FileNotFoundError(f"No files found in {self.folder}")

        for file in files:
            if not file.endswith('.gif'):
                continue

            try:
                with Image.open(os.path.join(self.folder, file)) as img:
                    if not img.is_animated():
                        logging.warning(f"Skipping non-animated file: {file}")
                        continue

                    self.frames.append(Frame(
                        ImageOps.pad(img, (self.width, self.height), Image.NEAREST, 0, tuple(img.getpixel((0, 0))),
                        img.info.get('duration'), img.info.get('loop')))
                    )
            except (IOError, OSError):
                logging.warning(f"Skipping corrupt file: {file}")

        if not self.frames:
            raise FileNotFoundError(f"No valid animated GIF files found in {self.folder}")

    def preload(self):
        for frame in self.frames:
            frame.image.load()

    def play(self):
        if not self.frames:
            self.load_files()

        self._start_time = time.monotonic()
        self._gif_start_time = self._start_time

        while True:
            frame = self.frames[self._current_frame]
            with canvas(self.display) as draw:
                draw.bitmap((0, 0), frame.image.convert('RGB'), fill='white')

            elapsed_time = time.monotonic() - self._start_time
            sleep_time = (frame.duration / 1000) - (time.monotonic() - self._gif_start_time)

            if sleep_time > 0:
                time.sleep(sleep_time)

            self._start_time = time.monotonic()

            if frame.loop > 0 and elapsed_time > frame.duration / 1000:
                self._gif_start_time = time.monotonic()
                self._current_frame = (self._current_frame + 1) % len(self.frames)

            if frame.loop == 0:
                self._current_frame = (self._current_frame + 1) % len(self.frames)

            if self._current_frame == 0:
                return True

    def run(self):
        self._is_running = True
        while self._is_running:
            try:
                if self.play():
                    self._current_frame = 0
            except Exception as e:
                logging.error(f"Error during animation: {e}")
                self.stop()

    def stop(self, signum=None, frame=None):
        self._is_running = False
        logging.info("Shutting down...")

