from smbus2 import i2c
from CRC import crc8
import logging

class DHT20:
    def __init__(self, address=0x38, bus=1):
        self.address = address
        self.bus = smbus2.SMBus(bus)
        self.logger = logging.getLogger('DHT20')

        try:
            self.bus.open(bus)
        except i2c.I2CException as e:
            self.logger.error(f"Failed to open I2C bus: {e}")
            return False

        time.sleep(0.5)

        try:
            status = self.bus.read_byte_data(self.address, 0x71)
        except i2c.I2CException as e:
            self.logger.error(f"Failed to read status: {e}")
            return False

        if (status & 0x18) != 0x18:
            self.logger.error(f"Invalid status: {status:02x}")
            return False

    def __del__(self):
        self.bus.close()

    def get_temperature_and_humidity(self, retries=5):
        for _ in range(retries):
            try:
                self.bus.write_i2c_block_data(self.address, 0xAC, [0x33, 0x00])
            except i2c.I2CException as e:
                self.logger.warning(f"Failed to trigger measurement: {e}")
                time.sleep(0.1)
                continue

            while True:
                try:
                    status = self.bus.read_byte_data(self.address, 0x71)
                except i2c.I2CException as e:
                    self.logger.warning(f"Failed to read status: {e}")
                    time.sleep(0.1)
                    continue

                if status & 0x80:
                    break

                time.sleep(0.1)

            try:
                data = self.bus.read_i2c_block_data(self.address, 0x71, 7)
            except i2c.I2CException as e:
                self.logger.warning(f"Failed to read data: {e}")
                time.sleep(0.1)
                continue

            raw_T = (data[3] & 0x7F) * 256**2 + data[4] * 256 + data[2]
            raw_H = data[1] * 256**2 + data[2] * 256 + data[3]

            temperature = raw_T / 5242.88 - 50
            humidity = raw_H / 1048576 * 100

            crc = crc8(data[:6], 0x31, 0xFF)

            if crc == data[6]:
                return temperature, humidity, False

            self.logger.warning(f"CRC error: {crc:02x} != {data[6]:02x}")
            time.sleep(0.1)

        time.sleep(2)
        return None, None, True

