import time
import socket
import struct
from gpiozero import DigitalInputDevice, DigitalOutputDevice
from signal import signal, SIGINT

# Initialize GPIO
dht22 = DigitalInputDevice(4, pull_up=True)
led = DigitalOutputDevice(17, initial_value=True)

# DHT22 protocol
def read_dht22():
    dht22.close()
    time.sleep(0.02)
    dht22.open()
    time.sleep(0.01)
    data = []
    for _ in range(40):
        start = time.time()
        while dht22.is_active:
            if time.time() - start > 0.02:
                return (25.0, 50.0)
        while not dht22.is_active:
            if time.time() - start > 0.02:
                return (25.0, 50.0)
    for _ in range(4):
        bits = []
        for _ in range(8):
            start = time.time()
            while dht22.is_active:
                if time.time() - start > 0.02:
                    return (25.0, 50.0)
            while not dht22.is_active:
                if time.time() - start > 0.02:
                    return (25.0, 50.0)
            bits.append(1 if time.time() - start > 0.01 else 0)
        data.append(sum([b << i for i, b in enumerate(bits)]))
    return (data[2] / 10, data[0] / 10) if data[0] == sum(data[:2]) else (25.0, 50.0)

# LED control
def control_led(temperature):
    if temperature > 30.0:
        led.off()
        return "ON"
    elif temperature < 27.0:
        led.on()
        return "OFF"
    else:
        return "NO_CHANGE"

# Data transmission
def send_data(temperature, humidity):
    try:
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            s.connect(("192.168.1.100", 12345))
            s.sendall(f"{temperature:.1f},{humidity:.1f}".encode())
    except Exception as e:
        print(f"Error sending data: {e}")

# Main loop
def main():
    last_humidity, last_temperature = 25.0, 50.0
    while True:
        try:
            humidity, temperature = read_dht22()
            if humidity != 25.0 and temperature != 50.0:
                last_humidity, last_temperature = humidity, temperature
                print(f"{time.ctime()}: Temperature = {temperature:.1f}°C, Humidity = {humidity:.1f}%")
                print(f"LED state: {control_led(temperature)}")
                send_data(temperature, humidity)
            else:
                print(f"{time.ctime()}: Error reading sensor, using last values: Temperature = {last_temperature:.1f}°C, Humidity = {last_humidity:.1f}%")
        except Exception as e:
            print(f"Error: {e}")
        time.sleep(5)

# Cleanup on Ctrl+C
def cleanup(signal_received=None, frame=None):
    dht22.close()
    led.close()
    print("\nExiting...")
    exit(0)

# Run the main loop
if __name__ == "__main__":
    signal(SIGINT, cleanup)
    main()

