    CRC_INIT = 0xFF
    CRC_FINAL = 0x00
    STATUS_MASK = 0x18
    STATUS_IDLE = 0x80
    ATTEMPTS = 10
    DELAY = 0.08
    RETRY_DELAY = 0.01
    MIN_INTERVAL = 2

    def __init__(self):
        self.bus = None
        self.last_measurement_time = 0
        self.cached_temp = None
        self.cached_humidity = None

    def begin(self):
        try:
            self.bus = smbus2.SMBus(self.I2C_BUS)
            time.sleep(0.5)
            status = self.bus.read_byte_data(self.I2C_ADDR, self.STATUS_REG)
            if (status & self.STATUS_MASK) != self.STATUS_IDLE:
                logging.error('Status check failed')
                return False
            return True
        except OSError as e:
            logging.error(f'Error opening I2C bus: {e}')
            return False

    def measure(self):
        try:
            self.bus.write_i2c_block_data(self.I2C_ADDR, self.MEASURE_REG, [0x33, 0x00])
            time.sleep(0.08)
            for _ in range(self.ATTEMPTS):
                status = self.bus.read_byte_data(self.I2C_ADDR, self.STATUS_REG)
                if (status & self.STATUS_IDLE) == 0:
                    time.sleep(self.DELAY)
                else:
                    break
