            if self.crc8(data[:6]) != data[6]:
                logging.warning('CRC mismatch')
                return self.measure()
            return data
        except OSError as e:
            logging.error(f'Error during measurement: {e}')
            return self.measure()

    def crc8(self, data):
        crc = self.CRC_INIT
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = ((crc << 1) ^ self.CRC_POLY) & 0xFF
                else:
                    crc <<= 1
        return crc

    def get_temperature_and_humidity(self):
        if time.time() - self.last_measurement_time < self.MIN_INTERVAL:
            return self.cached_temp, self.cached_humidity, None
        for _ in range(5):
