import time
import signal
import logging
from gpiozero import PWMOutputDevice
from subprocess import check_output

class FanController:
    def __init__(self):
        self.fan = PWMOutputDevice(14, frequency=100)
        self.exit_flag = False
        signal.signal(signal.SIGINT, self.exit_gracefully)
        signal.signal(signal.SIGTERM, self.exit_gracefully)

    def exit_gracefully(self, signum, frame):
        self.exit_flag = True

    def get_cpu_temp(self):
        try:
            temp_str = check_output("vcgencmd measure_temp", shell=True).decode()
            temp = float(temp_str.split('=')[1].split('\'')[0])
            return temp
        except Exception as e:
            logging.error(f"Failed to read CPU temperature: {e}")
            return None

    def set_fan_speed(self, temp):
        if temp is None:
            return
        if temp > 70:
            self.fan.value = 1.0
        elif temp > 60:
            self.fan.value = 0.85
        elif temp > 50:
            self.fan.value = 0.7
        elif temp > 40:
            self.fan.value = 0.5
        elif temp > 32:
            self.fan.value = 0.25
        elif temp > 25:
            self.fan.value = 0.15
        else:
            self.fan.value = 0.0

    def run(self):
        while not self.exit_flag:
            temp = self.get_cpu_temp()
            self.set_fan_speed(temp)
            logging.info(f"Current temperature: {temp}°C, Fan speed: {self.fan.value * 100}%")
            time.sleep(5)

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    controller = FanController()
    controller.run()

