import RPi.GPIO as GPIO
import time
import threading
import signal
import os

GPIO.setmode(GPIO.BCM)

# Assuming DOG is an object with send() and receive() methods
DOG = None

# Log file
log_file = None

# Background receive thread
receive_thread = None

def receive_data():
    while True:
        data = DOG.receive()
        if data:
            with open(log_file, 'a') as f:
                f.write(data + '\n')
        time.sleep(0.1)

def start_server(filename):
    global log_file, receive_thread
    log_file = filename
    receive_thread = threading.Thread(target=receive_data)
    receive_thread.start()

def stop_server():
    global receive_thread
    if receive_thread:
        receive_thread.join()

def send_data(data):
    DOG.send(data)

def write_data(data):
    with open(log_file, 'a') as f:
        f.write(data + '\n')

def display_data():
    with open(log_file, 'r') as f:
        print(f.read())

def exit_server():
    GPIO.cleanup()
    os._exit(0)

def handle_signal(signal, frame):
    stop_server()
    exit_server()

def main():
    signal.signal(signal.SIGINT, handle_signal)
    signal.signal(signal.SIGTERM, handle_signal)

    while True:
        command = input('> ')
        if command.startswith('start '):
            start_server(command.split(' ')[1])
        elif command == 'stop':
            stop_server()
        elif command == 'help':
            print('Commands: start <filename>, stop, help [command], display, send <data>, write <data>, exit')
        elif command == 'display':
            display_data()
        elif command.startswith('send '):
            send_data(command.split(' ')[1])
        elif command.startswith('write '):
            write_data(command.split(' ')[1])
        elif command == 'exit':
            exit_server()
        else:
            print('Unknown command. Type "help" for a list of commands.')

if __name__ == '__main__':
    try:
        main()
    except Exception as e:
        print('Error:', str(e))
        GPIO.cleanup()

