            if self.sensor.motion_detected:
                # Debounce
                time.sleep(self.debounce_time)
                if self.sensor.motion_detected:
                    self.detections.append(datetime.now().isoformat())
                    print(f"Motion detected at {self.detections[-1]}")

    def get_stats(self):
        return len(self.detections)

if __name__ == "__main__":
