        self.pwm = pwm
        self.last_msg = time.time()
        self.global_err_state = False
        self.error_output = None
        self.context = None
        self.subscriber = None

        try:
            if self.pwm:
                self.error_output = PWMOutputDevice(18, frequency=1000, duty_cycle=0)
            else:
                self.error_output = OutputDevice(15)
            self.error_output.on()

            self.context = zmq.Context()
            self.subscriber = self.context.socket(zmq.SUB)
            self.subscriber.connect("tcp://localhost:5555")
            self.subscriber.setsockopt(zmq.SUBSCRIBE, b"")

            signal.signal(signal.SIGINT, self.cleanup)
            signal.signal(signal.SIGTERM, self.cleanup)

        except Exception as e:
            logging.error(f"Failed to initialize GPIO: {e}")

    def update_error_output(self):
        if self.pwm:
            self.error_output.value = self.global_err_state
        else:
            self.error_output.on() if self.global_err_state else self.error_output.off()

    def set_error_output(self, state):
        self.global_err_state = state
        self.update_error_output()

    def cleanup(self, signum, frame):
        if self.error_output:
            self.error_output.off()
        if self.subscriber:
            self.subscriber.close()
        if self.context:
            self.context.term()
        exit(0)

    def handle_message(self):
        try:
            msg = self.subscriber.recv(zmq.NOBLOCK)
            if msg:
                self.last_msg = time.time()
                # Process the message
        except zmq.error.Again:
            if time.time() - self.last_msg > 20:
                self.set_error_output(True)

