            self.error_output.value = self.global_err_state
        else:
            self.error_output.on() if self.global_err_state else self.error_output.off()

    def set_error_output(self, state):
        self.global_err_state = state
        self.update_error_output()

    def cleanup(self, signum, frame):
        if self.error_output:
            self.error_output.off()
        if self.subscriber:
            self.subscriber.close()
        if self.context:
            self.context.term()
        exit(0)

    def handle_message(self):
        try:
            msg = self.subscriber.recv(zmq.NOBLOCK)
            if msg:
                self.last_msg = time.time()
                # Process the message
        except zmq.error.Again:
            if time.time() - self.last_msg > 20:
                self.set_error_output(True)
