import pigpio
import time

class OutputPin:
    def __init__(self, pin_number: int, initial_value: int):
        if not 0 <= pin_number <= 31:
            raise ValueError("Pin number must be between 0 and 31")
        if not 0 <= initial_value <= 1:
            raise ValueError("Initial value must be 0 or 1")

        self.pin_number = pin_number
        self.pi = pigpio.pi()

        if not self.pi.connected:
            raise ConnectionError("Could not connect to pigpio daemon")

        self.pi.set_mode(self.pin_number, pigpio.OUTPUT)
        self.set_value(initial_value)

    def set_value(self, value: int):
        if not 0 <= value <= 1:
            raise ValueError("Value must be 0 or 1")
        self.pi.write(self.pin_number, value)

    def shutdown(self):
        try:
            self.pi.set_mode(self.pin_number, pigpio.INPUT)
        finally:
            self.pi.stop()

if __name__ == '__main__':
    try:
        pin = OutputPin(17, 0)
        for _ in range(10):
            pin.set_value(1)
            time.sleep(0.5)
            pin.set_value(0)
            time.sleep(0.5)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        pin.shutdown()

