import RPi.GPIO as GPIO
import time
import signal
import argparse
import re

def get_raspi_model():
    with open('/proc/cpuinfo', 'r') as f:
        cpuinfo = f.read()
    match = re.search('Revision\s+:\s+([0-9a-f]+)', cpuinfo)
    if match:
        return int(match.group(1), 16)
    else:
        return None

def get_gpio_num(rev):
    if rev == 0x1000:
        return 17
    elif rev == 0x2000:
        return 26
    else:
        return None

def signal_handler(signal, frame):
    GPIO.cleanup()
    print('Exiting...')
    exit(0)

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("-d", "--debounce", type=int, default=200, help="Debounce time in ms")
    args = parser.parse_args()

    try:
        GPIO.setmode(GPIO.BCM)
    except RuntimeError:
        print('Error initializing GPIO. Exiting...')
        exit(1)

    model = get_raspi_model()
    gpio_num = get_gpio_num(model)
    gpio_ch = [i for i in range(gpio_num)] if gpio_num == 17 else [2, 3] + [i for i in range(4, gpio_num)]

    for ch in gpio_ch:
        GPIO.setup(ch, GPIO.IN)

    print(f'Detected model: Raspberry Pi {model}')
    print(f'GPIO count: {gpio_num}')
    print('Monitoring...')

    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    log = []
    while True:
        for ch in gpio_ch:
            GPIO.add_event_detect(ch, GPIO.BOTH, bouncetime=args.debounce)
            if GPIO.event_detected(ch):
                log.append((time.time(), ch, GPIO.input(ch)))
                if len(log) > 100:
                    log.pop(0)
        time.sleep(0.1)

if __name__ == "__main__":
    main()

