from random import uniform

# Define the sensor
sensor = DigitalInputDevice(17, pull_up=True)

# Define a function to generate a random amplitude
def generate_amplitude():
    if sensor.is_active:
        return uniform(3.0, 5.0)
    else:
        return uniform(6.0, 9.0)

# Main function
def main():
    try:
        # Initialize variables
        amplitudes = []

        # Loop indefinitely
        while True:
            # Read the sensor state every 0.3 seconds for 6 samples
            for _ in range(6):
                amplitudes.append(generate_amplitude())
                sleep(0.3)

            # Calculate the running average
            average = sum(amplitudes) / len(amplitudes)
            amplitudes = []

            # Print the result
            if average > 7.5:
                print("Maintenance recommended: wear trend is high")
            else:
                print("Component healthy: no action needed")

            # Sleep for a while before the next cycle
            sleep(1)

