def turn_on_leds():
    try:
        led1.on()
        led2.on()
    except Exception as e:
        print(f"Error occurred while turning on LEDs: {e}")

def turn_off_leds():
    try:
        led1.off()
        led2.off()
    except Exception as e:
        print(f"Error occurred while turning off LEDs: {e}")

def toggle_leds(cycles=5):
    if cycles <= 0:
        return
    try:
        led1.on()
        led2.on()
        time.sleep(1)
        led1.off()
        led2.off()
        time.sleep(1)
        toggle_leds(cycles-1)
    except Exception as e:
        print(f"Error occurred while toggling LEDs: {e}")

def cleanup():
    try:
        led1.close()
        led2.close()
    except Exception as e:
        print(f"Error occurred while cleaning up: {e}")

# Handle Ctrl+C
def signal_handler(signal, frame):
    cleanup()
    exit(0)

