import pigpio

class MotorError(Exception):
    pass

class Motor:
    def __init__(self, pi, pin):
        if not isinstance(pi, pigpio.pi):
            raise MotorError("Invalid pigpio.pi instance")
        self.pi = pi
        self.pin = pin
        self.pi.set_mode(pin, pigpio.OUTPUT)
        self.set_frequency(1000)
        self.set_duty_cycle(0)

    def set_frequency(self, freq):
        result = self.pi.set_PWM_frequency(self.pin, freq)
        if result < 0:
            raise MotorError(f"Failed to set PWM frequency: {result}")

    def set_duty_cycle(self, duty):
        if not isinstance(duty, int) or not 0 <= duty <= 255:
            raise MotorError("Duty cycle must be an integer in the range 0-255")
        result = self.pi.set_PWM_dutycycle(self.pin, duty)
        if result < 0:
            raise MotorError(f"Failed to set PWM duty cycle: {result}")

    def stop(self):
        self.set_duty_cycle(0)

    def __del__(self):
        self.stop()
        self.pi.stop()

    def close(self):
        self.__del__()

