import RPi.GPIO as GPIO
import time
import logging

class Servo:
    def __init__(self, pin=18, frequency=50):
        self.pin = pin
        self.frequency = frequency
        self._pwm = None
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(pin, GPIO.OUT)
            self._pwm = GPIO.PWM(pin, frequency)
            self._pwm.start(0)
        except Exception as e:
            logging.error(f"Failed to initialize servo on pin {pin} with frequency {frequency}: {e}")
            self.stop()

    def move_to(self, angle):
        if not 0 <= angle <= 180:
            logging.error(f"Invalid angle {angle}, must be between 0 and 180")
            return
        try:
            duty_cycle = self._angle_to_duty_cycle(angle)
            self._pwm.ChangeDutyCycle(duty_cycle)
            logging.info(f"Moved servo to {angle} degrees at {time.ctime()}")
        except Exception as e:
            logging.error(f"Failed to move servo to {angle} degrees: {e}")

    def stop(self):
        if self._pwm is not None:
            self._pwm.stop()
            GPIO.cleanup()

    def _angle_to_duty_cycle(self, angle):
        return 2.5 + angle / 180 * 10


def demo(servo, angles):
    try:
        for angle in angles:
            servo.move_to(angle)
            time.sleep(0.5)
        for angle in reversed(angles):
            servo.move_to(angle)
            time.sleep(0.5)
    except KeyboardInterrupt:
        logging.info("Stopping servo on keyboard interrupt")
    finally:
        servo.stop()


if __name__ == "__main__":
    servo = Servo(18, 50)
    if servo._pwm is not None:
        demo(servo, [0, 45, 90, 135, 180])

