def move_servo(channel, target_angle, step_size=5, delay=0.04):
    if channel < 0 or channel > 15:
        print("Channel must be between 0 and 15")
        return
    if target_angle < 0 or target_angle > 180:
        print("Angle must be between 0 and 180")
        return

    current_angle = kit.servo[channel].angle
    if current_angle is None:
        print(f"Servo on channel {channel} not found")
        return

    if current_angle < target_angle:
        for angle in range(current_angle, target_angle, step_size):
            kit.servo[channel].angle = angle
            time.sleep(delay)
    else:
        for angle in range(current_angle, target_angle, -step_size):
            kit.servo[channel].angle = angle
            time.sleep(delay)

# Define helper functions
def seek(angle):
    move_servo(SEEK, angle)

def deseek(angle):
    move_servo(SEEK, angle, step_size=2, delay=0.01)

def drop(angle):
    move_servo(DROP, angle)

def pick(angle):
    move_servo(GRAB, angle)

def grab(angle):
