        except serial.SerialException:
            print(f"Failed to open serial port {port} at {baud_rate} baud")
            raise

    def _send_command(self, command, timeout=1.0, wait_for=b'OK'):
        try:
            self.ser.write(f"{command}\r\n".encode())
            response = self.ser.read_until(wait_for, timeout)
            return response
        except serial.SerialException:
            print(f"Failed to send command {command}")
            return None

    def test_connection(self):
        return self._send_command('AT')

