import time
import signal

class ESP8266:
    def __init__(self):
        try:
            self.ser = serial.Serial(
                port='/dev/serial0', 
                baudrate=115200, 
                timeout=5, 
                write_timeout=5, 
                inter_byte_timeout=0.1, 
                rtscts=False, 
                dsrdtr=False, 
                xonxoff=False
            )
        except serial.SerialException:
            print("Failed to open serial port.")
            exit(1)

        signal.signal(signal.SIGTERM, self.cleanup)
        signal.signal(signal.SIGINT, self.cleanup)

    def _send_command(self, command, delay=1, max_retries=3):
        for _ in range(max_retries):
            self.ser.write((command + '\r\n').encode())
            time.sleep(delay)
            response = self._read_response()
            if response is not None:
                return response
        return None

    def _read_response(self):
        try:
            response = self.ser.read_until(b'\r\n', timeout=5).decode().strip()
            if response in ['OK', 'ERROR', 'FAIL']:
                return response
        except serial.SerialException:
            pass
        return None

