            return None, False
        with self.lock:
            item = {'id': self.next_id, 'name': name, 'done': done}
            self.next_id += 1
            self.data.append(item)
            return item, True


dm = DataManager()

@app.route('/data', methods=['GET'])
def get_data():
    return jsonify(dm.get_all()), 200

@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_by_id(item_id):
    item = dm.get_by_id(item_id)
    if item is None:
        return 'Not found', 404
    return jsonify(item), 200

@app.route('/data', methods=['POST'])
def create_data():
    data = request.get_json()
    item, created = dm.create(data.get('name'), data.get('done'))
    if not created:
        return 'Invalid input', 400
    return jsonify(item), 201

def shutdown_server(signum, frame):
    func = request.environ.get('werkzeug.server.shutdown')
    if func is None:
        raise RuntimeError('Not running with the Werkzeug Server')
    func()

if __name__ == '__main__':
    signal.signal(signal.SIGINT, shutdown_server)
    signal.signal(signal.SIGTERM, shutdown_server)
    app.run(host='0.0.0.0', port=5000, debug=False)
```

